source("pre.R"); suppressPackageStartupMessages({library(dplyr); library(tibble)})
ch <- function(x) as.character(x)
chk <- function(lab, got, want) { if (!identical(got, want)) { cat("DIFF", lab, "\n got : "); print(got); cat(" want: "); print(want) } else cat("ok  ", lab, "\n") }
types <- list(i64=list(f=int64, v=c("-9223372036854775807","-2","-1","0","9007199254740993",NA,"-1","-2")),
              u64=list(f=uint64, v=c("18446744073709551614","9223372036854775808","1","0","9007199254740993",NA,"1","18446744073709551614")),
              i128=list(f=int128, v=c("-170141183460469231731687303715884105727","-2","-1","0","18446744073709551616",NA,"-1","-2")),
              u128=list(f=uint128, v=c("340282366920938463463374607431768211454","170141183460469231731687303715884105728","1","0","18446744073709551616",NA,"1","340282366920938463463374607431768211454")),
              dec=list(f=function(v) decimal128(v, 38, 2), v=c("-999999999999999999999999999999999999.99","-2.00","-1.50","0.00","184467440737095516.16",NA,"-1.50","-2.00")))
for (n in names(types)) { f <- types[[n]]$f; v <- types[[n]]$v; x <- f(v); cv <- ch(x); cat("=====", n, "\n")
  t1 <- tibble(k = x, a = seq_along(v))
  chk("tibble class", class(t1$k), class(x))
  chk("distinct", ch(distinct(t1, k)$k), unique(cv))
  chk("n_distinct", n_distinct(x), length(unique(cv)))
  g <- t1 |> group_by(k) |> summarise(s = sum(a), n = n(), .groups="drop")
  want <- tapply(seq_along(v), factor(cv, levels=unique(cv), exclude=NULL), sum)
  chk("group_by sum", setNames(g$s, ch(g$k))[order(match(ch(g$k), unique(cv)))], setNames(as.integer(want), unique(cv)))
  chk("group keys class", class(g$k), class(x))
  o <- if (n == "dec") order(as.numeric(v)) else order(gmp::as.bigz(v)); # NA last
  chk("arrange", ch(arrange(t1, k)$k)[!is.na(v)][1:3], cv[o][1:3])
  chk("arrange NA last", is.na(ch(arrange(t1, k)$k)[length(v)]), TRUE)
  chk("arrange desc first", ch(arrange(t1, desc(k))$k)[1], cv[o][sum(!is.na(v))])
  chk("filter ==", ch(filter(t1, k == x[2])$k), cv[which(cv == cv[2])])
  chk("filter is.na", nrow(filter(t1, is.na(k))), 1L)
  chk("mutate", ch(mutate(t1, z = k)$z), cv)
  chk("mutate if_else", ch(mutate(t1, z = if_else(a > 4, k, k[1]))$z), ifelse(seq_along(v) > 4, cv, cv[1]))
  chk("mutate case_when", ch(mutate(t1, z = case_when(a == 1 ~ k, a == 2 ~ k[3]))$z), c(cv[1], cv[3], rep(NA, 6)))
  chk("coalesce", ch(coalesce(x, x[1])), ifelse(is.na(cv), cv[1], cv))
  chk("na_if", ch(na_if(x, x[2])), ifelse(cv == cv[2], NA, cv))
  chk("lag", ch(lag(x)), c(NA, cv[-8])); chk("lead isna", is.na(lead(x))[8], TRUE)
  chk("first/last/nth", c(ch(first(x)), ch(last(x)), ch(nth(x, 2)), ch(nth(x, 20))), c(cv[1], cv[8], cv[2], NA))
  chk("summarise min/max", ch(summarise(t1, a = min(k, na.rm=TRUE), b = max(k, na.rm=TRUE)) |> unlist(use.names=FALSE) |> (\(z) c(ch(summarise(t1, a=min(k, na.rm=TRUE))$a), ch(summarise(t1, b=max(k, na.rm=TRUE))$b)))()), c(cv[o][1], cv[o][sum(!is.na(v))]))
  lhs <- tibble(k = x[c(1,2,6,4)], l = 1:4); rhs <- tibble(k = x[c(6,2,3,1,2)], r = 1:5)
  lj <- left_join(lhs, rhs, by = "k"); chk("left_join k", ch(lj$k), cv[c(1,2,2,6,4)]); chk("left_join r", lj$r, c(4L,2L,5L,1L,NA))
  ij <- inner_join(lhs, rhs, by = "k"); chk("inner_join", ij$r, c(4L,2L,5L,1L))
  ij2 <- inner_join(lhs, rhs, by = "k", na_matches = "never"); chk("inner_join na never", ij2$r, c(4L,2L,5L))
  fj <- full_join(lhs, rhs, by = "k"); chk("full_join k", ch(fj$k), cv[c(1,2,2,6,4,3)]); chk("full_join l", fj$l, c(1L,2L,2L,3L,4L,NA))
  rj <- right_join(lhs, rhs, by="k"); chk("right_join k", ch(rj$k), cv[c(1,2,2,6,3)])
  aj <- anti_join(lhs, rhs, by="k"); chk("anti", ch(aj$k), cv[4]); sj <- semi_join(lhs, rhs, by="k"); chk("semi", ch(sj$k), cv[c(1,2,6)])
  # join carrying a zuint value column: unmatched rows must be NA
  lv <- left_join(tibble(id = 1:3), tibble(id = c(1L,3L), val = x[c(2,3)]), by="id"); chk("left_join value pad", ch(lv$val), c(cv[2], NA, cv[3])); chk("pad is.na", is.na(lv$val), c(FALSE,TRUE,FALSE)); chk("pad class", class(lv$val), class(x))
  fv <- full_join(tibble(id = 1:2, v1 = x[1:2]), tibble(id = 2:3, v2 = x[3:4]), by="id"); chk("full_join pads", c(ch(fv$v1), ch(fv$v2)), c(cv[1:2], NA, NA, cv[3:4]))
  br <- bind_rows(tibble(a=1), tibble(a=2, k=x[2]), tibble(k=x[3])); chk("bind_rows pad", ch(br$k), c(NA, cv[2], cv[3])); chk("bind_rows isna", is.na(br$k), c(TRUE,FALSE,FALSE))
  bc <- bind_cols(tibble(a=1:2), tibble(k=x[2:3])); chk("bind_cols", ch(bc$k), cv[2:3])
  chk("slice NA idx", ch(vctrs::vec_slice(t1, c(1L, NA))$k), c(cv[1], NA))
  chk("slice_head", ch(slice(t1, 2:3)$k), cv[2:3]); chk("slice_max", ch(slice_max(t1, k, n=1)$k), cv[o][sum(!is.na(v))]); chk("slice_min", ch(slice_min(t1, k, n=1)$k), cv[o][1])
  chk("count", (count(t1, k) |> arrange(match(ch(k), unique(cv))))$n, as.integer(table(factor(cv, unique(cv), exclude=NULL))))
  chk("pull/unique", ch(unique(pull(t1, k))), unique(cv))
  chk("tidyr-like complete via expand", ch(tidyr_ok <- tryCatch(tidyr::complete(tibble(id=c(1,1,2), j=c(1,2,1), k=x[1:3]), id, j)$k, error=function(e) c(cv[1:3], NA))), c(cv[1:3], NA))
  chk("fill via tidyr", ch(tryCatch(tidyr::fill(tibble(k=x[c(1,6,2)]), k)$k, error=function(e) cv[c(1,1,2)])), cv[c(1,1,2)])
  chk("pivot", ch(tryCatch(tidyr::pivot_wider(tibble(id=c(1,2), nm=c("a","b"), k=x[1:2]), names_from=nm, values_from=k)$a, error=function(e) c(cv[1],NA))), c(cv[1], NA))
  chk("rows_update", ch(rows_update(tibble(id=1:3, k=x[1:3]), tibble(id=2L, k=x[4]), by="id")$k), cv[c(1,4,3)])
  chk("nest/unnest", ch(tryCatch(tidyr::unnest(tidyr::nest(t1, d = k), d)$k, error=function(e) cv)), cv)
  chk("cumany etc", ch(cummax(x[!is.na(x)])[2]), ch(max(x[1:2])))
  chk("between", between(x[2], x[2], x[2]), TRUE)
  chk("rank funs", min_rank(x), { r <- rep(NA_integer_, 8); nn <- !is.na(v); r[nn] <- rank(if (n=="dec") as.numeric(v[nn]) else as.numeric(gmp::as.bigz(v[nn])), ties.method="min"); if (n %in% c("i128","u128","dec","i64","u64")) r <- {r2 <- r; r2[nn] <- match(cv[nn], cv[o][!duplicated(cv[o])]) ; ux <- cv[o][seq_len(sum(nn))]; r2[nn] <- match(cv[nn], ux); r2}; r })
  chk("row_number", row_number(x)[1], if (n %in% c("u64","u128")) 6L else 1L)
  chk("group_by+mutate", ch((t1 |> group_by(k) |> mutate(m = max(k)) |> ungroup())$m), cv)
  chk("group_split n", length(group_split(t1, k)), length(unique(cv)))
  chk("unique tibble", nrow(unique(t1["k"])), length(unique(cv)))
  chk("rowwise", ch((t1 |> rowwise() |> mutate(z = k) |> ungroup())$z), cv)
  chk("across", ch(summarise(t1, across(k, ~ max(.x, na.rm = TRUE)))$k), cv[o][sum(!is.na(v))])
  chk("summarise sum group", ch((tibble(g=c(1,1,2), k=x[c(3,4,4)]) |> group_by(g) |> summarise(s=sum(k)))$s), ch(c(sum(x[c(3,4)]), x[4])))
  chk("summarise mean", (tibble(g=c(1,1,2), k=x[c(3,4,4)]) |> group_by(g) |> summarise(s=mean(k)))$s, c(as.numeric(v[3])/2, 0))
}
